WITH with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM payments), islands AS (SELECT id, method, amount, paid_at, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT session_no, DATE_TRUNC('MONTH', paid_at) AS activity_month, COUNT(CASE WHEN method = 'promptpay' THEN 1 END) AS promptpay_count, PERCENTILE_APPROX(session_no, ARRAY(0.25, 0.5, 0.75)) AS session_no_quartiles, COUNT(*) AS event_count, PERCENT_RANK() OVER (PARTITION BY session_no ORDER BY COUNT(CASE WHEN method = 'promptpay' THEN 1 END) DESC) AS promptpay_count_percent_rank FROM islands GROUP BY session_no, DATE_TRUNC('MONTH', paid_at) ORDER BY activity_month NULLS LAST;
